const KEY='levelforge_v1';
const blank={profile:{name:'Wildan',title:'Sedang membangun diri',motto:'Bangun dirimu. Selangkah setiap hari.',bio:'',photo:'',email:''},skills:[],knowledge:[],projects:[],experience:[],certificates:[],achievements:[],quests:[],activity:[],xp:0,history:[],filter:'normal',districts:[]};
let data=load();let active='dashboard';let editPhotoData='',editPhotoOriginalData='';
function load(){try{let old=JSON.parse(localStorage.getItem(KEY)||'{}');let merged={...blank,...old};merged.profile={...blank.profile,...(old.profile||{})};merged.knowledge=(old.knowledge||[]).map(k=>({...k,cvSelected:!!k.cvSelected}));merged.rewards=Array.isArray(old.rewards)?old.rewards:[];merged.districts=Array.isArray(old.districts)?old.districts:[];return merged}catch(e){return structuredClone(blank)}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch(e){toast('Penyimpanan penuh. Kurangi ukuran PDF/foto atau cadangkan data.');return false}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dateKey(d=new Date()){return d.toISOString().slice(0,10)}
function fmtTanggal(d){if(!d)return '—';return new Date(d+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}
function levelInfo(xp){let lv=1,cur=xp;while(cur>=lv*150){cur-=lv*150;lv++}return {lv,cur,need:lv*150,pct:Math.round(cur/(lv*150)*100)}}
function todayActivity(){return data.activity.filter(a=>a.date===dateKey())}
function addActivity(title,xp,kind='Belajar'){let oldLevel=levelInfo(data.xp).lv;data.activity.unshift({id:Date.now(),date:dateKey(),title,kind,xp});data.xp+=xp;data.history.push({date:dateKey(),score:score()});save();let newLevel=levelInfo(data.xp).lv;if(newLevel>oldLevel){let milestones=[5,10,20,35,50,75,100].filter(m=>m>oldLevel&&m<=newLevel);if(milestones.length)window._evolutionToast=`LEVEL ${newLevel}! Evolusi karakter terbuka: ${evolutionInfo(newLevel).name}`;else window._levelToast=`LEVEL ${newLevel} tercapai!`}}
function activeDays(){return [...new Set(data.activity.map(a=>a.date))].sort()}
function streak(){const hari=activeDays();if(!hari.length)return 0;let s=0,d=new Date();if(!hari.includes(dateKey()))d.setDate(d.getDate()-1);while(hari.includes(dateKey(d))){s++;d.setDate(d.getDate()-1)}return s}
function bestStreak(){let hari=activeDays(),best=0,c=0,prev=null;hari.forEach(day=>{let dt=new Date(day+'T12:00:00');if(prev&&((dt-prev)/86400000===1))c++;else c=1;best=Math.max(best,c);prev=dt});return best}
function score(){let skillAvg=data.skills.length?data.skills.reduce((s,x)=>s+(Number(x.rating)||1),0)/(data.skills.length*5)*100:0;let projectScore=Math.min(data.projects.length*10,100);let knowledgeScore=Math.min(data.knowledge.length*5,100);let questScore=data.quests.length?data.quests.filter(q=>q.done).length/data.quests.length*100:0;let activityScore=Math.min(activeDays().length/30*100,100);return Math.round(skillAvg*.35+projectScore*.2+knowledgeScore*.15+questScore*.15+activityScore*.15)}
function logAction(title,xp=20,kind='Belajar'){addActivity(title,xp,kind);toast(window._evolutionToast||window._levelToast||`+${xp} XP • ${title}`);window._evolutionToast='';window._levelToast='';render()}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
const titles={dashboard:'Dasbor',identity:'Identitas',skills:'Pohon Keahlian',knowledge:'Gudang Ilmu',evolution:'Evolusi Karakter',achievements:'Pencapaian',projects:'Proyek',experience:'Pengalaman',certificates:'Sertifikat',quests:'Pusat Misi',growth:'Analisis Perkembangan',cv:'CV Otomatis',city:'Kota Pengetahuan'};
document.getElementById('nav').addEventListener('click',e=>{let b=e.target.closest('button[data-page]');if(!b)return;active=b.dataset.page;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));render()});
document.getElementById('closeModal').onclick=closeModal;document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});
function openModal(title,fields,submitText='Simpan',onSimpan){document.getElementById('modalTitle').textContent=title;let form=document.getElementById('modalForm');form.innerHTML=`<div class="form-grid">${fields.map(f=>fieldHTML(f)).join('')}</div><div class="form-submit"><button class="button" type="submit">${submitText}</button></div>`;form.querySelectorAll('[data-category-select]').forEach(sel=>{let custom=form.querySelector(`[data-category-custom]`);const update=()=>{if(!custom)return;let show=sel.value==='__custom__';custom.style.display=show?'':'none';custom.required=show;if(!show)custom.value=''};sel.addEventListener('change',update);update()});form.onsubmit=e=>{e.preventDefault();let fd=new FormData(form),obj={};fields.forEach(f=>{if(f.type==='category-select'){let selected=fd.get(f.name);obj[f.name]=selected==='__custom__'?(fd.get(f.customName)||'').trim():selected}else obj[f.name]=fd.get(f.name)});if(fields.some(f=>f.type==='category-select'&&obj[f.name]==='')){toast('Isi kategori ilmu yang kamu tulis sendiri.');return}let uploadField=fields.find(f=>f.type==='file');if(uploadField){let file=fd.get(uploadField.name);if(file&&file.size){let reader=new FileReader();reader.onload=()=>{if(uploadField.name==='file'){obj.file=reader.result;obj.fileType=file.type}else{obj[uploadField.name]=reader.result;obj[uploadField.name+'Type']=file.type}onSimpan(obj);closeModal();render()};reader.readAsDataURL(file);return}}onSimpan(obj);if(window._evolutionToast||window._levelToast){toast(window._evolutionToast||window._levelToast);window._evolutionToast='';window._levelToast=''}closeModal();render()};document.getElementById('modal').classList.remove('hidden')}
function fieldHTML(f){let value=esc(f.value||'');let cls=f.full?' full':'';if(f.type==='category-select'){let opts=[...f.options];if(f.value&&!opts.includes(f.value))opts.splice(opts.length-1,0,f.value);let customSelected=!opts.includes(f.value)&&!!f.value;return `<div class="field${cls}"><label>${f.label}</label><select name="${f.name}" data-category-select><option value="">Pilih kategori ilmu</option>${opts.filter(o=>o!=='__custom__').map(o=>`<option value="${esc(o)}" ${o===f.value?'selected':''}>${esc(o)}</option>`).join('')}<option value="__custom__" ${customSelected?'selected':''}>Lainnya — ketik sendiri</option></select><input name="${f.customName}" type="text" data-category-custom placeholder="Ketik kategori ilmu sendiri..." value="${customSelected?value:''}" style="margin-top:8px;${customSelected?'':'display:none'}" ${customSelected?'required':''}></div>`}if(f.type==='file')return `<div class="field${cls}"><label>${f.label}</label><input name="${f.name}" type="file" accept="${esc(f.accept||'*/*')}" ${f.required?'required':''}></div>`;if(f.type==='textarea')return `<div class="field${cls}"><label>${f.label}</label><textarea name="${f.name}" placeholder="${esc(f.placeholder||'')}">${value}</textarea></div>`;if(f.type==='select')return `<div class="field${cls}"><label>${f.label}</label><select name="${f.name}">${f.options.map(o=>`<option ${o===f.value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;return `<div class="field${cls}"><label>${f.label}</label><input name="${f.name}" type="${f.type||'text'}" value="${value}" placeholder="${esc(f.placeholder||'')}" ${f.required?'required':''} ${f.step?'step="'+f.step+'"':''}></div>`}
function closeModal(){document.getElementById('modal').classList.add('hidden')}
function addButton(label,fn,secondary=false){return `<button class="button ${secondary?'secondary':''} small-btn" data-action="${fn}">${label}</button>`}
function actionsBar(text,btn){return `<div class="toolbar"><p>${text}</p>${btn}</div>`}
function empty(text){return `<div class="empty">${text}</div>`}
function statCard(label,value,sub,icon){return `<div class="card"><div class="stat-icon">${icon}</div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div>`}
function profilePhoto(){return data.profile.photo||''}
function render(){document.getElementById('pageTitle').textContent=titles[active];document.getElementById('todayLabel').textContent=new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase();document.getElementById('sideNama').textContent=data.profile.name||'Nama Anda';document.getElementById('sideTitle').textContent=data.profile.title||'Sedang membangun diri';let side=document.getElementById('sidePhoto');if(profilePhoto()){side.src=profilePhoto();side.style.display='block'}else{side.style.display='none'}document.getElementById('content').innerHTML=pages[active]();bindActions();}
const pages={dashboard:dashboardPage,identity:identityPage,skills:skillsPage,knowledge:knowledgePage,evolution:evolutionPage,achievements:achievementsPage,projects:projectsPage,experience:experiencePage,certificates:certificatesPage,quests:questsPage,growth:growthPage,cv:cvPage,city:knowledgeCityPage};
function dashboardPage(){let li=levelInfo(data.xp),today=todayActivity(),st=streak(),sc=score(),completed=data.quests.filter(q=>q.done).length;let qlist=data.quests.filter(q=>!q.done).slice(0,4);return `<div class="card hero"><div><span class="eyebrow">SISTEM PENGEMBANGAN DIRI</span><h2>Tempa versi terbaik dirimu.</h2><p>${esc(data.profile.motto||'Kemajuan kecil yang dilakukan setiap hari akan menjadi luar biasa.')}</p><div class="actions">${addButton('+ Catat Belajar','loglearning')}${addButton('+ Tambah Misi','addquest',true)}</div></div><div class="hero-side"><div class="level">LV ${li.lv}</div><div class="xp">${data.xp.toLocaleString()} TOTAL XP</div><div class="progress" style="width:190px"><i style="width:${li.pct}%"></i></div><div class="xp">${li.cur} / ${li.need} XP menuju level berikutnya</div></div></div>${characterCard(li.lv)}<div class="card dashboard-profile"><img class="dash-photo" src="${profilePhoto()||''}" style="${profilePhoto()?'':'display:none'}" alt="Foto profil"><div><h2>${esc(data.profile.name||'Nama Anda')}</h2><p>${esc(data.profile.title||'Sedang membangun diri')}</p><small>${esc(data.profile.email||'Email belum ditambahkan')}</small></div></div><div class="grid stats" style="margin:16px 0">${statCard('SKOR PERKEMBANGAN',sc+'%','Indeks perkembangan diri','↗')}${statCard('STREAK SAAT INI',st+' hari',`Streak terbaik: ${bestStreak()} hari`,'🔥')}${statCard('KEAHLIAN TERCATAT',data.skills.length,`${data.skills.filter(s=>s.rating>=4).length} mahir / kuat`,'✦')}${statCard('PROYEK',data.projects.length,'Bukti portofolio','⌘')}</div><div class="grid two"><div class="card"><div class="card-head"><h3>Kurva perkembangan</h3><span class="badge">TERKINI</span></div>${miniChart()}</div><div class="card"><div class="card-head"><h3>Misi hari ini</h3>${addButton('Lihat semua','gotoquests',true)}</div>${qlist.length?qlist.map(q=>questLine(q)).join(''):empty('Belum ada misi aktif. Buat misi kecil untuk hari ini.')}</div></div><div class="grid two" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Aktivitas terbaru</h3><span class="muted">+ XP</span></div>${today.concat(data.activity.filter(a=>a.date!==dateKey()).slice(0,4)).slice(0,5).map(a=>`<div class="item-row"><div><b>${esc(a.title)}</b><small>${fmtTanggal(a.date)} · ${esc(a.kind)}</small></div><div class="right"><strong>+${a.xp}</strong></div></div>`).join('')||empty('Mulai catat proses belajar atau pencapaian untuk membangun riwayatmu.')}</div><div class="card"><div class="card-head"><h3>Pengingat potensi</h3></div><div class="alert-box">${st===0?'Belum ada aktivitas hari ini. Sesi 10 menit cukup untuk memulai kembali.':'Momentum-mu masih terjaga. Pertahankan konsistensi, tetapi utamakan pekerjaan bermakna, bukan sekadar mencentang.'}<br><br><b>Konsistensi lebih baik daripada semangat besar yang tidak bisa dipertahankan.</b></div></div></div>`}
function identityPage(){if(data.profile.photo&&!editPhotoOriginalData){editPhotoOriginalData=data.profile.photo;editPhotoData=data.profile.photo}return `<div class="grid two"><div class="card"><div class="card-head"><h3>Identitas pribadi</h3>${addButton('Simpan profil','saveprofile')}</div><div style="display:flex;gap:22px;align-items:center;flex-wrap:wrap"><img class="photo-preview" id="photoPreview" src="${profilePhoto()}" style="${profilePhoto()?'':'display:none'}"><div><b>${esc(data.profile.name||'Nama Anda')}</b><p class="muted" style="font-size:12px">${esc(data.profile.title||'Gelar pribadi')}</p><span class="badge">LV ${levelInfo(data.xp).lv} · ${data.xp} XP</span></div></div><div class="photo-tools"><label class="button secondary small-btn" for="photoUnggah">Unggah foto</label><input type="file" id="photoUnggah" accept="image/*" hidden>${addButton('Hapus foto','removephoto',true)}</div><p class="muted" style="font-size:11px;margin-top:15px">Unggah foto, lalu pilih filter untuk tampilan profil. Tekan Terapkan untuk menyimpan hasil edit.</p><div class="photo-filters actions" style="margin-top:10px"><button data-filter="normal" class="selected">Normal</button><button data-filter="professional">Profesional</button><button data-filter="mono">Monokrom</button><button data-filter="warm">Hangat</button><button data-filter="cool">Sejuk</button></div><canvas id="photoCanvas" width="600" height="600" style="display:none"></canvas><div class="photo-tools">${addButton('Terapkan edit foto','applyphoto')}${addButton('Unduh hasil edit','downloadphoto',true)}</div></div><div class="card"><h3>Detail profil</h3><div class="field" style="margin:14px 0"><label>Nama</label><div>${esc(data.profile.name||'—')}</div></div><div class="field" style="margin:14px 0"><label>Gelar pribadi</label><div>${esc(data.profile.title||'—')}</div></div><div class="field" style="margin:14px 0"><label>Motto pribadi</label><div>${esc(data.profile.motto||'—')}</div></div><div class="field"><label>Email untuk dihubungi</label><p class="muted">${esc(data.profile.email||'Belum diisi')}</p></div><div class="field"><label>Tentang saya</label><p class="muted" style="font-size:12px">${esc(data.profile.bio||'Tuliskan ringkasan profil melalui tombol Simpan profil.')}</p></div><button class="button secondary small-btn" data-action="saveprofile">Ubah detail profil</button></div></div>`}
function skillsPage(){return `${actionsBar('Catat kemampuanmu. Beri penilaian jujur dan tambahkan bukti seiring perkembangan.',addButton('+ Tambah keahlian','addskill'))}<div class="grid three">${data.skills.map((s,i)=>`<div class="card"><div class="card-head"><h3>${esc(s.name)}</h3><span class="badge">${esc(s.category)}</span></div><div class="skill-meter"><span>Lv ${s.rating}/5</span><div class="progress"><i style="width:${s.rating*20}%"></i></div><b>${s.rating*20}%</b></div><p class="muted" style="font-size:11px">${esc(s.evidence||'Bukti belum ditambahkan')}</p>${s.evidenceFile?`<div class="skill-proof">${s.evidenceFileType==='application/pdf'?`<iframe src="${s.evidenceFile}" title="Bukti ${esc(s.name)}"></iframe>`:`<img src="${s.evidenceFile}" alt="Bukti ${esc(s.name)}">`}<a href="${s.evidenceFile}" download="bukti-${esc(s.name)}">Unduh bukti</a></div>`:''}<div class="actions">${addButton('Ubah','editskill:'+i,true)}${addButton('Hapus','delskill:'+i,true)}</div></div>`).join('')||empty('Belum ada keahlian tercatat. Tambahkan keahlian yang sedang kamu pelajari.')}</div>`}
function openKnowledgeEditor(index=null){const k=index===null?{}:data.knowledge[index];const edit=index!==null;openModal(edit?'Ubah catatan ilmu':'Tambah catatan ilmu',[{name:'title',label:'Topik / konsep',value:k.title||'',required:true},{name:'category',label:'Kategori ilmu',type:'category-select',options:categoryOptions(),customName:'categoryCustom',value:k.category||'',required:true},{name:'date',label:'Tanggal',type:'date',value:k.date||dateKey()},{name:'rating',label:'Tingkat pemahaman (1–5)',type:'number',value:k.rating||'3'},{name:'summary',label:'Apa yang kamu pahami?',type:'textarea',value:k.summary||'',full:true},{name:'font',label:'Font',type:'select',value:k.font||'DM Sans',options:['DM Sans','Arial','Georgia','Courier New','Verdana']},{name:'textFormat',label:'Format',type:'select',value:k.textFormat||'Normal',options:['Normal','Tebal','Miring','Tebal & Miring']},{name:'application',label:'Bagaimana kamu menerapkannya?',type:'textarea',value:k.application||'',full:true},{name:'file',label:'Lampiran PDF atau foto (opsional)',type:'file',accept:'application/pdf,image/*'}],edit?'Simpan perubahan':'Simpan catatan',o=>{if(edit){data.knowledge[index]={...k,...o,cvSelected:!!k.cvSelected};}else{data.knowledge.unshift(o);addActivity('Ilmu dicatat: '+o.title,15,'Ilmu')}save()});const form=document.getElementById('modalForm'),textarea=form.querySelector('[name="summary"]');if(!textarea)return;textarea.style.display='none';const toolbar=document.createElement('div');toolbar.className='rich-toolbar';toolbar.innerHTML='<button type="button" data-cmd="bold"><b>B</b></button><button type="button" data-cmd="italic"><i>I</i></button><button type="button" data-cmd="underline"><u>U</u></button><button type="button" data-cmd="insertUnorderedList">• List</button><button type="button" data-cmd="insertOrderedList">1. List</button><button type="button" data-cmd="justifyLeft">Rata kiri</button><button type="button" data-cmd="justifyCenter">Tengah</button><button type="button" data-cmd="justifyRight">Rata kanan</button><button type="button" data-cmd="removeFormat">Bersihkan format</button><button type="button" data-fullscreen="1">⛶ Luaskan</button>';const editor=document.createElement('div');editor.className='rich-editor';editor.contentEditable='true';editor.setAttribute('role','textbox');editor.setAttribute('aria-multiline','true');editor.innerHTML=k.summary||'';editor.dataset.placeholder='Tulis atau rapikan ilmu yang kamu pahami di sini...';textarea.parentElement.append(toolbar,editor);editor.addEventListener('input',()=>textarea.value=editor.innerHTML);toolbar.addEventListener('click',e=>{let btn=e.target.closest('button');if(!btn)return;if(btn.dataset.fullscreen){document.getElementById('modal').classList.toggle('editor-fullscreen');return}editor.focus();document.execCommand(btn.dataset.cmd,false,null);editor.dispatchEvent(new Event('input',{bubbles:true}))});form.addEventListener('submit',()=>{textarea.value=editor.innerHTML},{capture:true});}

let knowledgeView='archive';let activeBookId=null;
function knowledgeAttachment(k){if(!k.file)return '';return `<div class="knowledge-attachment">${k.fileType==='application/pdf'?`<iframe src="${k.file}" title="PDF ${esc(k.title)}"></iframe>`:`<img src="${k.file}" alt="Lampiran ${esc(k.title)}">`}<a href="${k.file}" download="${esc(k.title)}-lampiran">Unduh lampiran</a></div>`}
function knowledgePage(){
 const categories=[...new Set(data.knowledge.map(k=>k.category).filter(Boolean))];
 const shown=knowledgeCategoryFilter?data.knowledge.filter(k=>k.category===knowledgeCategoryFilter):[];
 const select='<div class="card knowledge-filter"><label>Pilih kategori ilmu untuk membuka arsip</label><select id="knowledgeCategoryFilter"><option value="">— Pilih kategori —</option>'+categories.map(c=>'<option value="'+esc(c)+'" '+(c===knowledgeCategoryFilter?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></div>';
 const cards=shown.map(k=>{const i=data.knowledge.indexOf(k);return `<div class="card"><div class="card-head"><h3>${esc(k.title)}</h3><span class="badge">${esc(k.category)}</span></div><p class="muted" style="font-size:11px">${fmtTanggal(k.date)} · Pemahaman ${k.rating||1}/5</p><div class="knowledge-body" style="font-family:${esc(k.font||'DM Sans')};font-weight:${['Tebal','Tebal & Miring'].includes(k.textFormat)?'700':'400'};font-style:${['Miring','Tebal & Miring'].includes(k.textFormat)?'italic':'normal'}">${k.summary||'Belum ada ringkasan'}</div>${knowledgeAttachment(k)}<p class="muted" style="font-size:11px">Penerapan: ${esc(k.application||'—')}</p><div class="actions">${addButton('📖 Baca sebagai buku','openbook:'+i,true)}${addButton(k.cvSelected?'✓ Tampil di CV':'☆ Masukkan ke CV','toggleknowledgecv:'+i,true)}${addButton('Ubah','editknowledge:'+i,true)}${addButton('Hapus','delknowledge:'+i,true)}</div></div>`}).join('');
 const books=data.knowledge.map((k,i)=>`<div class="card book-entry"><div class="card-head"><h3>${esc(k.title)}</h3><span class="badge">${esc(k.category)}</span></div><p class="muted">${fmtTanggal(k.date)}</p><button class="button secondary small-btn" data-action="openbook:${i}">Baca buku</button></div>`).join('');
 const book=activeBookId!==null&&data.knowledge[activeBookId]?data.knowledge[activeBookId]:null;
 const bookScreen=book?`<div class="book-reader card"><div class="book-toolbar"><button class="button secondary small-btn" data-action="closebook">← Kembali ke rak</button><button class="button small-btn" data-action="printbook">Cetak buku / PDF</button></div><article class="book-page"><div class="book-cover"><small>BLOUNCER · GUDANG ILMU</small><h1>${esc(book.title)}</h1><p>${esc(book.category)}</p><small>${fmtTanggal(book.date)}</small></div><h2>${esc(book.title)}</h2><div class="book-content">${book.summary||'<p>Belum ada isi.</p>'}</div>${book.application?`<section class="book-application"><h3>Penerapan</h3><p>${esc(book.application)}</p></section>`:''}${book.file?`<section><h3>Lampiran</h3>${knowledgeAttachment(book)}</section>`:''}<footer>Ditulis dan disimpan oleh pemilik BLOUNCER LEVEL FORGE.</footer></article></div>`:'';
 return actionsBar('Gudang Ilmu: catatanmu kini bisa diedit leluasa, dilampiri PDF, dan dibaca sebagai buku.',`${addButton('+ Tambah catatan ilmu','addknowledge')} ${addButton('📚 Rak Buku','knowledgebooks',true)}`)+ (knowledgeView==='books'?`<div class="card"><h3>Rak Buku Pribadi</h3><p class="muted">Setiap catatan ilmu otomatis masuk menjadi buku.</p></div><div class="grid three">${books||empty('Belum ada buku. Tambahkan catatan ilmu.')}</div>`:bookScreen||select+(knowledgeCategoryFilter?'<div class="grid two">'+(cards||empty('Belum ada catatan untuk kategori ini.'))+'</div>':empty('Pilih kategori di atas. Catatan ilmu tidak ditampilkan sebelum kategori dipilih.')));
}
function achievementsPage(){let earned=data.achievements;let system=[['LANGKAH PERTAMA','Catat keahlian pertamamu',data.skills.length>0],['KREATOR','Selesaikan sebuah proyek',data.projects.some(p=>p.status==='Selesai')],['PENCARI ILMU','Simpan 10 catatan ilmu',data.knowledge.length>=10],['KONSISTEN','Bangun streak 7 hari',bestStreak()>=7],['POLIMAT','Catat keahlian dalam 5 kategori',new Set(data.skills.map(s=>s.category)).size>=5],['PEMBUAT PROYEK','Buat 5 proyek',data.projects.length>=5]];return `<div class="grid three">${system.map(a=>`<div class="card"><div class="stat-icon">${a[2]?'🏅':'◇'}</div><h3>${a[0]}</h3><p class="muted" style="font-size:11px">${a[1]}</p><span class="badge">${a[2]?'TERBUKA':'TERKUNCI'}</span></div>`).join('')}</div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Pencapaian khusus</h3>${addButton('+ Tambah pencapaian','addachievement')}</div>${earned.map((a,i)=>`<div class="item-row"><div><b>${esc(a.title)}</b><small>${fmtTanggal(a.date)} · ${esc(a.description||'')}</small></div><div class="list-actions">${addButton('Hapus','delachievement:'+i,true)}</div></div>`).join('')||empty('Catat tonggak perjalanan dan buka pencapaian pribadi.')}</div>`}
function projectsPage(){return `${actionsBar('Proyek membuktikan kemampuanmu. Sertakan peran, alat, hasil, dan tautan.',addButton('+ Tambah proyek','addproject'))}<div class="grid two">${data.projects.map((p,i)=>`<div class="card"><div class="card-head"><h3>${esc(p.name)}</h3><span class="badge">${esc(p.status)}</span></div><p class="muted" style="font-size:11px">${esc(p.role||'Peran belum ditentukan')} · ${esc(p.tools||'Alat belum ditentukan')}</p><p style="font-size:12px;line-height:1.6">${esc(p.description||'')}</p>${p.result?`<p class="stat-sub">Hasil: ${esc(p.result)}</p>`:''}${p.link?`<a href="${esc(p.link)}" target="_blank" rel="noopener" style="color:var(--green);font-size:11px">Lihat proyek ↗</a>`:''}<div class="actions" style="margin-top:12px">${addButton('Ubah','editproject:'+i,true)}${addButton('Hapus','delproject:'+i,true)}</div></div>`).join('')||empty('Proyek yang kamu selesaikan akan menjadi bukti portofoliomu.')}</div>`}
function experiencePage(){return `${actionsBar('Catat pekerjaan, mengajar, relawan, organisasi, freelance, dan pengalaman praktik.',addButton('+ Tambah pengalaman','addexperience'))}<div class="grid two">${data.experience.map((x,i)=>`<div class="card"><h3>${esc(x.role)}</h3><p class="muted" style="font-size:11px">${esc(x.organization)} · ${esc(x.period||'')}</p><p style="font-size:12px;line-height:1.6">${esc(x.description||'')}</p><div class="actions">${addButton('Ubah','editexperience:'+i,true)}${addButton('Hapus','delexperience:'+i,true)}</div></div>`).join('')||empty('Tambahkan pengalaman kerja dan kehidupan, termasuk peran nonformal.')}</div>`}
function certificatesPage(){return `${actionsBar('Arsipkan sertifikat dan bukti pelatihan.',addButton('+ Tambah sertifikat','addcertificate'))}<div class="grid three">${data.certificates.map((c,i)=>`<div class="card"><div class="stat-icon">▧</div><h3>${esc(c.name)}</h3><p class="muted" style="font-size:11px">${esc(c.issuer)} · ${fmtTanggal(c.date)}</p>${c.file?`<div class="certificate-preview">${c.fileType==='application/pdf'?`<iframe src="${c.file}" title="Sertifikat PDF"></iframe>`:`<img src="${c.file}" alt="Foto sertifikat">`}<a href="${c.file}" download="${esc(c.name)}-bukti">Unduh bukti asli</a></div>`:''}<p style="font-size:12px">${esc(c.details||'')}</p><div class="actions">${addButton('Ubah','editcertificate:'+i,true)}${addButton('Hapus','delcertificate:'+i,true)}</div></div>`).join('')||empty('Belum ada sertifikat tersimpan.')}</div>`}
function questLine(q){return `<div class="quest"><input type="checkbox" data-quest="${q.id}" ${q.done?'checked':''}><div class="quest-text ${q.done?'done':''}">${esc(q.title)}</div><span class="xp-tag">${q.xp} XP</span></div>`}
function questsPage(){return `${actionsBar('Buat misi kecil dan jelas. Menyelesaikannya akan mencatat aktivitas dan memberi XP.',addButton('+ Tambah misi','addquest'))}<div class="grid two"><div class="card"><div class="card-head"><h3>Misi aktif</h3><span class="badge">${data.quests.filter(q=>!q.done).length} TERSISA</span></div>${data.quests.filter(q=>!q.done).map(q=>questLine(q)).join('')||empty('Semua misi saat ini selesai. Buat misi baru.')}</div><div class="card"><div class="card-head"><h3>Misi selesai</h3></div>${data.quests.filter(q=>q.done).map(q=>questLine(q)).join('')||empty('Misi yang telah selesai akan muncul di sini.')}</div></div>`}
function growthPage(){let sc=score(),li=levelInfo(data.xp),cat={};data.skills.forEach(s=>{cat[s.category]??=[];cat[s.category].push(Number(s.rating||1)*20)});let metrics=[['Keahlian',data.skills.length?Math.round(data.skills.reduce((a,s)=>a+s.rating*20,0)/data.skills.length):0],['Proyek',Math.min(100,data.projects.length*10)],['Ilmu',Math.min(100,data.knowledge.length*5)],['Penyelesaian misi',data.quests.length?Math.round(data.quests.filter(q=>q.done).length/data.quests.length*100):0],['Konsistensi',Math.min(100,Math.round(activeDays().length/30*100))]];return `<div class="grid stats">${statCard('SKOR PERKEMBANGAN',sc+'%','Dihitung dari catatanmu','↗')}${statCard('TOTAL XP',data.xp.toLocaleString(),'Diperoleh dari aktivitas','⚡')}${statCard('STREAK TERBAIK',bestStreak()+' hari','Rekor hari berturut-turut','🔥')}${statCard('HARI AKTIF',activeDays().length,'Hari dengan progres tercatat','◷')}</div><div class="card growth-profile"><div class="growth-head">${profilePhoto()?`<img src="${profilePhoto()}" alt="Foto profil">`:''}<div><h3>${esc(data.profile.name||'Nama Anda')}</h3><small>${esc(data.profile.title||'')}</small></div><div class="growth-character" data-character-rotate>${characterSVG(Math.max(0,['ROOKIE','AWAKENED','WARRIOR','ELITE','MASTER','LEGEND','MYTHIC','ASCENDANT'].indexOf(evolutionInfo(li.lv).name)))}</div></div></div><div class="grid two" style="margin-top:16px"><div class="card"><h3>Perkembangan dari waktu ke waktu</h3>${miniChart(true)}</div><div class="card"><h3>Faktor perkembangan</h3>${metrics.map(m=>`<div class="skill-meter"><span style="width:105px">${m[0]}</span><div class="progress"><i style="width:${m[1]}%"></i></div><b>${m[1]}%</b></div>`).join('')}<p class="muted" style="font-size:10px;margin-top:12px">Skor ini adalah indeks pemantauan pribadi, bukan ukuran kemampuan yang tervalidasi.</p></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Kalender konsistensi</h3><span class="badge">84 HARI TERAKHIR</span></div>${heatmap()}</div><div class="card" style="margin-top:16px"><h3>Rincian keahlian</h3>${Object.entries(cat).map(([k,v])=>`<div class="skill-meter"><span style="width:120px">${esc(k)}</span><div class="progress"><i style="width:${Math.round(v.reduce((a,b)=>a+b,0)/v.length)}%"></i></div><b>${Math.round(v.reduce((a,b)=>a+b,0)/v.length)}%</b></div>`).join('')||empty('Tambahkan keahlian untuk melihat perkembangan kategori.')}</div>`}
function cvPage(){let p=data.profile,cvKnowledge=data.knowledge.filter(k=>k.cvSelected);return `<div class="toolbar"><p>CV hanya menampilkan ilmu yang kamu pilih. Gudang Ilmu tetap menjadi arsip lengkap, tidak otomatis memenuhi CV.</p><div class="actions">${addButton('Cetak / Simpan PDF','printcv')}${addButton('Unduh teks CV','downloadcv',true)}</div></div><div class="card cv-curate"><b>KURASI CV — PILIH YANG TERBAIK</b><p class="muted">Ilmu dipilih: ${cvKnowledge.length} dari ${data.knowledge.length} catatan · Keluarkan catatan yang kurang relevan agar CV tetap ringkas.</p>${data.knowledge.map((k,i)=>`<div class="item-row"><div><b>${esc(k.title)}</b><small>${esc(k.category)} · Pemahaman ${k.rating||1}/5</small></div><div>${addButton(k.cvSelected?'✓ Dipilih':'☆ Pilih','toggleknowledgecv:'+i,true)}</div></div>`).join('')||empty('Belum ada ilmu di Gudang Ilmu. Tambahkan catatan terlebih dahulu.')}</div><div class="cv-paper" id="cvPaper"><div class="cv-top">${p.photo?`<img class="cv-photo" src="${p.photo}" alt="Foto CV">`:''}<h2>${esc(p.name||'NAMA ANDA')}</h2><b>${esc(p.title||'Jabatan profesional')}</b><p>${esc(p.email||'')}</p><p>${esc(p.bio||'Ringkasan diri: Tambahkan deskripsi singkat di menu Identitas.')}</p></div>${data.skills.length?`<h3>Keahlian</h3><ul>${data.skills.map(s=>`<li>${esc(s.name)} — ${esc(s.category)} (${s.rating*20}% penilaian mandiri)</li>`).join('')}</ul>`:''}${data.experience.length?`<h3>Pengalaman</h3>${data.experience.map(x=>`<p><b>${esc(x.role)}</b> — ${esc(x.organization)} (${esc(x.period||'')})<br>${esc(x.description||'')}</p>`).join('')}`:''}${data.projects.length?`<h3>Proyek</h3>${data.projects.map(x=>`<p><b>${esc(x.name)}</b> — ${esc(x.role||'')}<br>${esc(x.description||'')}${x.tools?`<br>Alat: ${esc(x.tools)}`:''}${x.result?`<br>Hasil: ${esc(x.result)}`:''}</p>`).join('')}`:''}${data.certificates.length?`<h3>Sertifikat</h3><ul>${data.certificates.map(c=>`<li>${esc(c.name)} — ${esc(c.issuer)} (${fmtTanggal(c.date)})</li>`).join('')}</ul>`:''}${cvKnowledge.length?`<h3>Ilmu Pilihan</h3>${cvKnowledge.map(k=>`<p><b>${esc(k.title)}</b> — ${esc(k.summary||'')}</p>`).join('')}`:''}</div><p class="muted" style="font-size:10px;margin-top:12px">CV ini adalah draf dari catatanmu sendiri. Periksa kembali sebelum dikirim kepada perekrut.</p>`}

const rewardCatalog=[
 {xp:50,name:'Pedang Pemula',icon:'🗡️'},{xp:100,name:'Tongkat Latihan',icon:'🥢'},{xp:150,name:'Cangkul Petani',icon:'⛏️'},{xp:250,name:'Ilmu Pedang',icon:'⚔️'},{xp:300,name:'Silat Harimau',icon:'🐅'},{xp:400,name:'Perisai Baja',icon:'🛡️'},{xp:500,name:'Tombak Penjaga',icon:'🔱'},{xp:650,name:'Tendangan Elang',icon:'🥋'},{xp:800,name:'Kapak Penjelajah',icon:'🪓'},{xp:1000,name:'Busur Pemburu',icon:'🏹'},{xp:1250,name:'Sabit Pertanian',icon:'🌾'},{xp:1500,name:'Palu Master',icon:'🔨'},{xp:2000,name:'Aura Naga',icon:'🐉'},{xp:2500,name:'Pedang Legenda',icon:'⚔️'},{xp:3000,name:'Jurus Elang',icon:'🦅'},{xp:5000,name:'Armor Ascendant',icon:'👑'},{xp:6000,name:'Jurus Angin',icon:'🌪️'},{xp:7500,name:'Keris Emas',icon:'🗡️'},{xp:10000,name:'Cangkul Legenda',icon:'⛏️'},{xp:15000,name:'Singa Penakluk',icon:'🦁'}];
function characterAction(el){if(el){el.classList.remove('character-spin');void el.offsetWidth;el.classList.add('character-spin');setTimeout(()=>el.classList.remove('character-spin'),900)}try{let ctx=new (window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.setValueAtTime(250,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(600,ctx.currentTime+.22);g.gain.setValueAtTime(.13,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.4);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.42)}catch(e){}}

function evolutionInfo(level){let stages=[{min:1,max:4,name:'ROOKIE',title:'Pemula',reward:'Karakter dasar',icon:'⚔️'},{min:5,max:9,name:'AWAKENED',title:'Terbangun',reward:'Aura Awakened',icon:'✨'},{min:10,max:19,name:'WARRIOR',title:'Pejuang',reward:'Armor Warrior',icon:'🛡️'},{min:20,max:34,name:'ELITE',title:'Elite',reward:'Perlengkapan Elite',icon:'⚡'},{min:35,max:49,name:'MASTER',title:'Master',reward:'Aura Master',icon:'👑'},{min:50,max:74,name:'LEGEND',title:'Legenda',reward:'Armor Legend',icon:'🌟'},{min:75,max:99,name:'MYTHIC',title:'Mythic',reward:'Efek Mythic',icon:'💠'},{min:100,max:9999,name:'ASCENDANT',title:'Ascendant',reward:'Evolusi Ascendant',icon:'🏆'}];return stages.find(x=>level>=x.min&&level<=x.max)||stages[0]}
function characterSVG(stage){
 const colors=['#9ba8b9','#70b9ff','#4c9fff','#c6a45b','#f2c95f','#d9e7ff','#b4a4ff','#ffe99c'];
 const c=colors[Math.max(0,Math.min(7,stage))], armored=stage>=2, helmet=stage>=6, crowned=stage>=4;
 const broad=stage>=5?36:stage>=2?31:25;
 const armor=armored?`<path d="M72 75 Q100 62 128 75 L134 112 Q120 128 100 132 Q80 128 66 112 Z" fill="#284563" stroke="${c}" stroke-width="3"/><path d="M82 82 L100 89 L118 82 L121 108 L100 120 L79 108 Z" fill="#b68d43" stroke="#f1d27a" stroke-width="2"/><path d="M100 90 L100 117" stroke="#f5d57a" stroke-width="3"/>`:`<path d="M${100-broad} 75 Q100 64 ${100+broad} 75 L${100+broad+3} 113 Q100 128 ${100-broad-3} 113 Z" fill="#31577e" stroke="${c}" stroke-width="3"/>`;
 const shoulder=armored?`<path d="M72 76 L52 83 L60 101 L78 96 M128 76 L148 83 L140 101 L122 96" fill="#8c7045" stroke="${c}" stroke-width="3"/>`:'';
 const headgear=helmet?`<path d="M74 44 Q100 20 126 44 L122 64 L111 72 L89 72 L78 64 Z" fill="#425c7d" stroke="${c}" stroke-width="3"/><path d="M83 50 L117 50 M100 37 L100 68" stroke="#d9b75c" stroke-width="3"/>` : crowned?`<path d="M78 38 L86 21 L100 34 L114 21 L122 38 L126 46 L74 46 Z" fill="#e6bd51" stroke="#fff0a6" stroke-width="2"/>`:'';
 const wings=stage>=6?`<path d="M70 78 Q18 38 25 98 Q40 117 68 110 M130 78 Q182 38 175 98 Q160 117 132 110" fill="none" stroke="${c}" stroke-width="7" stroke-linecap="round"/>`:'';
 const cape=stage>=3?`<path d="M75 75 L48 148 L64 166 L81 122 L119 122 L136 166 L152 148 L125 75" fill="#18304f" stroke="${c}" stroke-width="2"/>`:'';
 const legs=armored?`<path d="M82 120 L99 125 L93 158 L82 173 L69 171 L74 151 Z M101 125 L118 120 L126 151 L131 171 L118 173 L107 158 Z" fill="#344d70" stroke="${c}" stroke-width="3"/><path d="M68 171 L94 171 L97 181 L65 183 Z M105 171 L132 171 L135 183 L103 181 Z" fill="#b08b49" stroke="#f0d17a" stroke-width="2"/>`:`<path d="M82 117 L98 124 L93 165 L80 173 L72 169 Z M102 124 L118 117 L128 169 L120 173 L107 165 Z" fill="#28476c" stroke="${c}" stroke-width="3"/><path d="M71 169 L94 169 L97 180 L66 182 Z M106 169 L129 169 L134 182 L103 180 Z" fill="#a98645"/>`;
 const gear=(data.equippedRewards||[]).map(n=>rewardCatalog.find(r=>r.name===n)).filter(Boolean);
 const icons=gear.slice(0,2).map((r,i)=>`<text class="gear-emoji gear-swing" x="${i===0?50:150}" y="128" font-size="25" text-anchor="middle" transform="rotate(${i===0?-25:25} ${i===0?50:150} 128)">${r.icon}</text>`).join('');
 return `<svg class="hero-character human-character" viewBox="0 0 200 200" role="img" aria-label="Karakter manusia level ${stage+1}"><circle cx="100" cy="103" r="82" fill="${c}" opacity=".10"/>${wings}<path d="M76 76 Q62 83 59 102 L52 126 L64 132 L76 111 L82 94 M124 76 Q138 83 141 102 L148 126 L136 132 L124 111 L118 94" fill="#c99568" stroke="${c}" stroke-width="3" stroke-linecap="round"/>${cape}<circle cx="100" cy="52" r="24" fill="#d6a276" stroke="${c}" stroke-width="3"/>${headgear}<path d="M91 71 L109 71 L112 80 L100 86 L88 80 Z" fill="#c99568"/>${shoulder}${armor}<path d="M83 116 L117 116 L119 123 L100 130 L81 123 Z" fill="#c29b55" stroke="${c}" stroke-width="2"/>${legs}<circle cx="91" cy="54" r="2.5" fill="#172b43"/><circle cx="109" cy="54" r="2.5" fill="#172b43"/><path d="M92 63 Q100 67 108 63" fill="none" stroke="#7a4435" stroke-width="2"/>${icons}</svg>`;
}
function equippedGearBadge(){let equipped=(data.equippedRewards||[]).map(n=>rewardCatalog.find(r=>r.name===n)).filter(Boolean);return equipped.length?`<div class="equipped-gear-list">${equipped.map(r=>`<span title="${esc(r.name)}" class="equipped-gear-item"><i>${r.icon}</i>${esc(r.name)}</span>`).join('')}</div>`:`<div class="equipped-gear-empty">Belum memasang reward — pilih item di Gudang Reward.</div>`}
function characterCard(level){let st=evolutionInfo(level),stage=['ROOKIE','AWAKENED','WARRIOR','ELITE','MASTER','LEGEND','MYTHIC','ASCENDANT'].indexOf(st.name);return `<div class="card character-card"><div class="character-visual"><div class="character-rotator" data-character-rotate>${characterSVG(stage)}</div><span class="character-label">${st.name}</span>${equippedGearBadge()}</div><div class="character-details"><span class="eyebrow">KARAKTERMU · EVOLUSI ${stage+1}/8</span><h2>${st.title}</h2><p>Karakter tumbuh seiring usaha dan levelmu. Evolusi berikutnya membuka pada level ${[5,10,20,35,50,75,100][Math.min(stage,6)]||100}.</p><div class="actions">${addButton('Lihat hadiah & evolusi','gotoevolution',true)}</div></div></div>`}
function evolutionPage(){let level=levelInfo(data.xp).lv,stage=evolutionInfo(level),milestones=[1,5,10,20,35,50,75,100];return `<div class="card character-card evolution-feature"><div class="character-visual"><div class="character-rotator" data-character-rotate>${characterSVG(milestones.indexOf(stage.min))}</div><span class="character-label">${stage.name}</span>${equippedGearBadge()}</div><div class="character-details"><span class="eyebrow">EVOLUSI KARAKTER</span><h2>${stage.title} · Level ${level}</h2><p>Setiap pencapaian level membuka perubahan karakter. Selesaikan misi, bangun skill, dan kumpulkan bukti nyata agar progresmu tidak sekadar angka.</p></div></div><div class="card reward-inventory"><h3>Gudang Reward (XP)</h3><p>Reward akan terbuka sesuai XP. Klik untuk memasang atau melepas.</p><div class="reward-grid">${rewardCatalog.map(r=>{let unlocked=data.xp>=r.xp,equipped=(data.equippedRewards||[]).includes(r.name);return `<button class="reward-chip ${unlocked?'unlocked':'locked'} ${equipped?'equipped':''}" data-reward-name="${esc(r.name)}" ${unlocked?'':'disabled'}><span>${r.icon}</span><b>${esc(r.name)}</b><small>${r.xp} XP · ${unlocked?(equipped?'Terpasang':'Terbuka'):'Terkunci'}</small></button>`}).join('')}</div></div><div class="grid two">${milestones.map((lv,i)=>{let prev=milestones[i-1]||0,unlock=level>=lv;let name=['Rookie','Awakened','Warrior','Elite','Master','Legend','Mythic','Ascendant'][i];let reward=['Karakter awal','Aura Awakened','Armor Warrior','Perlengkapan Elite','Aura Master','Armor Legend','Efek Mythic','Evolusi Ascendant'][i];return `<div class="card reward-card ${unlock?'unlocked':'locked'}"><div class="stat-icon">${unlock?'🏆':'🔒'}</div><h3>Level ${lv} · ${name}</h3><p>${reward}</p><span class="badge">${unlock?'TERBUKA':'TERKUNCI'}</span></div>`}).join('')}</div>`}
