function normCategory(s){return String(s||'').toLowerCase().trim().replace(/[^a-z0-9\s&/+-]/g,'').replace(/\s+/g,' ')}
function getDistricts(){let districts=knowledgeDistrictSeeds.map(seed=>({name:seed[0],icon:seed[1],aliases:seed[2],first:seed[3],last:seed[4],custom:false}));(data.districts||[]).forEach(d=>{if(!districts.some(x=>normCategory(x.name)===normCategory(d.name)))districts.push({...d,custom:true,aliases:[d.name]})});let categoryNames=[...data.knowledge.map(k=>k.category),...data.skills.map(k=>k.category)].map(x=>String(x||'').trim()).filter(Boolean);categoryNames.forEach(name=>{let normalized=normCategory(name);let recognized=districts.some(d=>(d.aliases||[d.name]).some(a=>normalized===normCategory(a)||normalized.includes(normCategory(a))||normCategory(a).includes(normalized)));if(!recognized&&!districts.some(d=>normCategory(d.name)===normalized))districts.push({name,icon:'📘',aliases:[name],first:'Ruang ilmu khusus',last:'Pusat keahlian khusus',custom:true,auto:true})});return districts}
function districtStats(d){let aliases=(d.aliases||[d.name]).map(normCategory),notes=data.knowledge.filter(k=>aliases.some(a=>a===normCategory(k.category)||normCategory(k.category).includes(a)||a.includes(normCategory(k.category))));let skills=data.skills.filter(k=>aliases.some(a=>a===normCategory(k.category)||normCategory(k.category).includes(a)||a.includes(normCategory(k.category))));let kp=notes.reduce((sum,k)=>sum+25+(Math.max(1,Math.min(5,Number(k.rating)||1))*5),0)+skills.reduce((sum,k)=>sum+Number(k.rating||1)*15,0);let thresholds=[0,30,100,250,500,1000],tier=0;thresholds.forEach((t,i)=>{if(kp>=t)tier=i});let customers=[0,2,5,10,18,30][tier];return {notes,skills,kp,tier,customers,threshold:thresholds[tier],next:thresholds[tier+1]||null}}
function knowledgeCityPage(){let districts=getDistricts(),activeDistricts=districts.filter(d=>districtStats(d).notes.length||districtStats(d).skills.length),totalKP=activeDistricts.reduce((a,d)=>a+districtStats(d).kp,0),totalCustomers=activeDistricts.reduce((a,d)=>a+districtStats(d).customers,0);return `<div class="card city-hero"><div><span class="eyebrow">KNOWLEDGE CITY · PERADABAN ILMU</span><h2>Ilmu yang kamu pelajari, membangun duniamu.</h2><p>Catatan dan keahlian yang kamu simpan akan membuka distrik, menaikkan bangunan, serta menambah aktivitas warga secara simulasi.</p><div class="actions">${addButton('+ Buat distrik ilmu','adddistrict')}${addButton('Lihat Gudang Ilmu','gotoknowledge',true)}</div></div><div class="city-metrics"><b>${activeDistricts.length}<small>DISTRIK AKTIF</small></b><b>${totalKP.toLocaleString('id-ID')}<small>KNOWLEDGE POINT</small></b><b>${totalCustomers}<small>WARGA SIMULASI</small></b></div></div><div class="city-stage-guide card"><b>TINGKAT EVOLUSI DISTRIK</b><div class="city-tier-list">${['🌱 Awal','🏠 Berkembang','🏢 Profesional','🏙️ Elite','🏛️ Master','✨ Legendaris'].map((t,i)=>`<span>${t}</span>`).join('')}</div><small>KP berasal dari catatan ilmu dan skill yang dicatat. Ini indikator game, bukan sertifikasi kompetensi nyata.</small></div><h3 class="section-title">Distrik yang kamu bangun (${activeDistricts.length})</h3><div class="grid two">${activeDistricts.map(d=>districtCard(d)).join('')||empty('Kota masih berupa lahan kosong. Tambahkan catatan ilmu di Gudang Ilmu dengan kategori, misalnya PSIKOLOGI, EKONOMI, SIPIL, atau AGAMA. Distrik akan terbuka otomatis.')}</div><h3 class="section-title">20 distrik tersedia</h3><div class="grid three">${districts.filter(d=>!activeDistricts.includes(d)).map(d=>`<div class="card city-locked"><span class="city-icon">${d.icon}</span><b>${esc(d.name)}</b><small>Belum terbuka · Tambahkan catatan ilmu kategori ini untuk membangun distrik.</small></div>`).join('')||empty('Semua distrik telah terbuka!')}</div>`}
function districtCard(d){let st=districtStats(d),stageNames=['Awal','Berkembang','Profesional','Elite','Master','Legendaris'],buildings=['Lahan & tenda belajar',d.first||'Bangunan awal','Gedung utama',d.last||'Kompleks elite','Kampus/kompleks master','Landmark distrik'],icons=['🌱','🏠','🏢','🏙️','🏛️','✨'];let progress=st.next?Math.max(0,Math.min(100,Math.round((st.kp-st.threshold)/(st.next-st.threshold)*100))):100;let stars='★'.repeat(st.tier+1)+'☆'.repeat(5-st.tier);return `<div class="card district-card tier-${st.tier}"><div class="district-top"><span class="city-icon">${d.icon}</span><span class="badge">${stageNames[st.tier]}</span></div><h3>${esc(d.name)}</h3><div class="district-building">${icons[st.tier]}<b>${esc(buildings[st.tier])}</b></div><div class="district-stars">${stars}</div><div class="district-stats"><span>📖 ${st.notes.length} catatan</span><span>✦ ${st.skills.length} skill</span><span>👥 ${st.customers} warga</span></div><div class="progress"><i style="width:${progress}%"></i></div><small class="muted">${st.kp} KP ${st.next?`· ${Math.max(0,st.next-st.kp)} KP menuju ${stageNames[st.tier+1]}`:'· Tingkat tertinggi'}</small></div>`}
function miniChart(big=false){let points=data.history.slice(-12);if(!points.length)points=[{score:score(),date:dateKey()}];let w=600,h=190,pad=26;let vals=points.map(x=>x.score);let coords=vals.map((v,i)=>`${pad+i*(w-2*pad)/Math.max(1,vals.length-1)},${h-pad-v*(h-2*pad)/100}`).join(' ');let circles=vals.map((v,i)=>`<circle cx="${pad+i*(w-2*pad)/Math.max(1,vals.length-1)}" cy="${h-pad-v*(h-2*pad)/100}" r="3" fill="#a7f36a"/>`).join('');return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${pad}" y1="${pad}" x2="${w-pad}" y2="${pad}" stroke="#29362d"/><line x1="${pad}" y1="${h/2}" x2="${w-pad}" y2="${h/2}" stroke="#29362d"/><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="#29362d"/><polyline points="${coords}" fill="none" stroke="#a7f36a" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${circles}</svg></div><div class="muted" style="font-size:10px">Score snapshots appear as aktivitas are recorded.</div>`}
function heatmap(){let hari=Array.from({length:84},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(83-i));return dateKey(d)});return `<div class="calendar">${hari.map(day=>{let n=data.activity.filter(a=>a.date===day).length;return `<div class="heat ${n?`l${Math.min(4,n)}`:''}" title="${day}: ${n} aktivitas"></div>`}).join('')}</div><div class="heat-label">Sedikit <span class="heat l1" style="display:inline-block;width:10px"></span> <span class="heat l2" style="display:inline-block;width:10px"></span> <span class="heat l3" style="display:inline-block;width:10px"></span> <span class="heat l4" style="display:inline-block;width:10px"></span> Banyak</div>`}
function bindActions(){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>runAction(el.dataset.action)));document.querySelectorAll('[data-quest]').forEach(el=>el.addEventListener('change',()=>toggleMisi(el.dataset.quest,el.checked)));}
function toggleMisi(id,done){let q=data.quests.find(q=>String(q.id)===String(id));if(!q)return;if(done&&!q.done){q.done=true;addActivity(`Misi selesai: ${q.title}`,Number(q.xp||50),'Misi');toast(window._evolutionToast||window._levelToast||`Misi selesai • +${q.xp} XP`);window._evolutionToast='';window._levelToast=''}else if(!done){q.done=false;save()}render()}
