if(a.startsWith('editproject:')){let i=+a.split(':')[1],p=data.projects[i];return openModal('Ubah proyek',[{name:'name',label:'Nama',value:p.name,required:true},{name:'role',label:'Peran',type:'category-select',options:['Pemimpin proyek','Pendiri','Desainer','Pengembang','Peneliti','Analis','Manajer','Anggota tim','Pelaksana','Konsultan','Relawan'],customName:'roleCustom',value:p.role},{name:'status',label:'Status',type:'select',value:p.status,options:['Sedang dikerjakan','Selesai','Direncanakan']},{name:'tools',label:'Alat',value:p.tools},{name:'link',label:'Tautan',value:p.link},{name:'description',label:'Deskripsi',type:'textarea',value:p.description,full:true},{name:'result',label:'Hasil / dampak',type:'textarea',value:p.result,full:true}], 'Perbarui',o=>{data.projects[i]=o;save()})}if(a.startsWith('delproject:'))return removeItem('projects',+a.split(':')[1]);
if(a==='addexperience')return openModal('Tambah pengalaman',[{name:'role',label:'Peran / posisi',type:'category-select',options:['Guru','Mahasiswa','Freelancer','Wirausaha','Relawan','Magang','Karyawan','Pengurus organisasi','Pemimpin tim','Peneliti'],customName:'roleCustom',required:true},{name:'organization',label:'Organisasi',required:true},{name:'period',label:'Periode',placeholder:'Jan 2025 – sekarang'},{name:'description',label:'Tanggung jawab / pencapaian',type:'textarea',full:true}], 'Simpan pengalaman',o=>{data.experience.unshift(o);save()});if(a.startsWith('editexperience:')){let i=+a.split(':')[1],x=data.experience[i];return openModal('Ubah pengalaman',[{name:'role',label:'Peran',type:'category-select',options:['Guru','Mahasiswa','Freelancer','Wirausaha','Relawan','Magang','Karyawan','Pengurus organisasi','Pemimpin tim','Peneliti'],customName:'roleCustom',value:x.role,required:true},{name:'organization',label:'Organisasi',value:x.organization,required:true},{name:'period',label:'Periode',value:x.period},{name:'description',label:'Deskripsi',type:'textarea',value:x.description,full:true}], 'Perbarui',o=>{data.experience[i]=o;save()})}if(a.startsWith('delexperience:'))return removeItem('experience',+a.split(':')[1]);
if(a==='addcertificate')return openModal('Tambah sertifikat',[{name:'name',label:'Sertifikat / pelatihan',required:true},{name:'issuer',label:'Penerbit / lembaga',required:true},{name:'date',label:'Tanggal diterbitkan',type:'date',value:dateKey()},{name:'details',label:'Detail',type:'textarea',full:true},{name:'file',label:'Unggah sertifikat asli (PDF / gambar)',type:'file',accept:'application/pdf,image/*'}], 'Simpan sertifikat',o=>{data.certificates.unshift(o);save()});if(a.startsWith('editcertificate:')){let i=+a.split(':')[1],c=data.certificates[i];return openModal('Ubah sertifikat',[{name:'name',label:'Nama',value:c.name,required:true},{name:'issuer',label:'Penerbit',value:c.issuer,required:true},{name:'date',label:'Tanggal',type:'date',value:c.date},{name:'details',label:'Detail',type:'textarea',value:c.details,full:true},{name:'file',label:'Ganti bukti (PDF / gambar)',type:'file',accept:'application/pdf,image/*'}], 'Perbarui',o=>{data.certificates[i]={...c,...o};save()})}if(a.startsWith('delcertificate:'))return removeItem('certificates',+a.split(':')[1]);
