function removeItem(key,i){if(!confirm('Hapus entri ini? Tindakan ini tidak dapat dibatalkan.'))return;data[key].splice(i,1);save();render()}
function cvText(){let p=data.profile;let sections=[];sections.push(`${p.name||'NAMA ANDA'}\n${p.title||'Jabatan profesional'}\n\n${p.bio||''}`);if(data.skills.length)sections.push('KEAHLIAN\n'+data.skills.map(s=>`• ${s.name} (${s.category}) — ${s.rating}/5`).join('\n'));if(data.experience.length)sections.push('PENGALAMAN\n'+data.experience.map(x=>`${x.role} — ${x.organization} (${x.period})\n${x.description}`).join('\n\n'));if(data.projects.length)sections.push('PROYEK\n'+data.projects.map(x=>`${x.name} — ${x.role}\n${x.description}\nAlat: ${x.tools}\nHasil: ${x.result}${x.link?'\nTautan: '+x.link:''}`).join('\n\n'));if(data.certificates.length)sections.push('SERTIFIKAT\n'+data.certificates.map(c=>`${c.name} — ${c.issuer} (${c.date})`).join('\n'));let selected=data.knowledge.filter(k=>k.cvSelected);if(selected.length)sections.push('ILMU PILIHAN\n'+selected.map(k=>`• ${k.title} — ${k.summary||''}`).join('\n'));return sections.join('\n\n')}
function downloadText(content,filename,type){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.getElementById('content').addEventListener('change',e=>{if(e.target.id==='knowledgeCategoryFilter'){knowledgeCategoryFilter=e.target.value;render()}});
// Photo editing: canvas filters, resize/crop square, local-only
let photoFilter='normal';document.getElementById('content').addEventListener('change',e=>{if(e.target.id!=='photoUnggah'||!e.target.files[0])return;let file=e.target.files[0],reader=new FileReader();reader.onload=()=>{editPhotoOriginalData=reader.result;editPhotoData=reader.result;renderPhotoPreview()};reader.readAsDataURL(file)});
function renderPhotoPreview(){let img=new Image();img.onload=()=>{let canvas=document.getElementById('photoCanvas'),ctx=canvas.getContext('2d'),size=600;canvas.width=canvas.height=size;let scale=Math.max(size/img.width,size/img.height),w=img.width*scale,h=img.height*scale;ctx.clearRect(0,0,size,size);ctx.filter=photoFilter==='mono'?'grayscale(1) contrast(1.1)':photoFilter==='professional'?'contrast(1.08) saturate(.82) brightness(1.04)':photoFilter==='warm'?'sepia(.22) saturate(1.25) brightness(1.04)':photoFilter==='cool'?'saturate(.9) hue-rotate(12deg) brightness(1.02)':'none';ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);editPhotoData=canvas.toDataURL('image/png');let p=document.getElementById('photoPreview');p.src=editPhotoData;p.style.display='block'};img.src=editPhotoOriginalData||editPhotoData}
document.getElementById('content').addEventListener('click',e=>{let reward=e.target.closest('[data-reward-name]');if(reward){let name=reward.dataset.rewardName;data.equippedRewards??=[];let at=data.equippedRewards.indexOf(name);if(at>=0)data.equippedRewards.splice(at,1);else data.equippedRewards.push(name);save();render();return}let character=e.target.closest('[data-character-rotate]');if(character){characterAction(character);return}let f=e.target.closest('[data-filter]');if(!f)return;photoFilter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===f));if(editPhotoData)renderPhotoPreview()});
// Karakter dapat diputar manual dengan menyeret mouse atau jari
let characterDrag=null;
document.getElementById('content').addEventListener('pointerdown',e=>{let target=e.target.closest('[data-character-rotate]');if(!target)return;characterDrag={target,x:e.clientX,angle:target._angle||0};target.setPointerCapture?.(e.pointerId)});
document.getElementById('content').addEventListener('pointermove',e=>{if(!characterDrag)return;let angle=characterDrag.angle+(e.clientX-characterDrag.x);characterDrag.target.style.transform='rotateY('+angle+'deg)';characterDrag.target._angle=angle});
document.getElementById('content').addEventListener('pointerup',()=>characterDrag=null);
// Cadangkan and restore JSON
document.getElementById('backupBtn').onclick=()=>downloadText(JSON.stringify(data,null,2),'blouncer-level-forge-backup.json','application/json');document.getElementById('restoreBtn').onclick=()=>document.getElementById('restoreInput').click();document.getElementById('restoreInput').onchange=e=>{let file=e.target.files[0];if(!file)return;let r=new FileReader();r.onload=()=>{try{let parsed=JSON.parse(r.result);if(!parsed.profile||!Array.isArray(parsed.skills))throw Error('File tidak valid');data={...blank,...parsed};save();render();toast('Cadangan berhasil dipulihkan')}catch(err){toast('File cadangan tidak valid')}};r.readAsText(file)};

// Suara antiklik: bunyi singkat setiap tombol/aksi ditekan.
let uiAudioCtx;
function playTapSound(){
  try{
    uiAudioCtx ||= new (window.AudioContext || window.webkitAudioContext)();
    if(uiAudioCtx.state==='suspended') uiAudioCtx.resume();
    const osc=uiAudioCtx.createOscillator(), gain=uiAudioCtx.createGain();
    osc.type='sine'; osc.frequency.setValueAtTime(620,uiAudioCtx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(880,uiAudioCtx.currentTime+0.045);
    gain.gain.setValueAtTime(0.0001,uiAudioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.055,uiAudioCtx.currentTime+0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001,uiAudioCtx.currentTime+0.085);
    osc.connect(gain);gain.connect(uiAudioCtx.destination);
    osc.start();osc.stop(uiAudioCtx.currentTime+0.09);
  }catch(err){/* Audio tidak didukung: aplikasi tetap berjalan normal. */}
}
document.addEventListener('click',e=>{
  if(e.target.closest('button,[role="button"],label.button')) playTapSound();
},true);

// print style: only CV section
document.addEventListener('DOMContentLoaded',render);render();

if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}
